"""Author the fixed Linux read-only Pager request owner in existing HIA.

Static authoring only. No generation or execution was performed when this file
was written. The independent assembly transport is an explicit bootstrap
dependency. It is not a Core opcode, generic FFI, Python page provider, or proof
of a complete SQLite implementation.
"""
from __future__ import annotations
import ast
import hashlib
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.pager_owner_lock_source_r3 import SOURCE as LOCK_SOURCE
from tools.pager_owner_page_source import SOURCE as PAGE_SOURCE
from tools.pager_owner_common_source_r2 import SOURCE as COMMON_SOURCE

RETAINED_PATH = Path(__file__).with_name('sqlite_pager_retained_owner.hia')
RETAINED_BYTES = RETAINED_PATH.read_bytes()
if hashlib.sha256(RETAINED_BYTES).hexdigest() != '3c9ec1a7e570c27bdf879c1d88f810bb1dd9598800c36c0a9b144d9f16ede7f9':
    raise ValueError('frozen retained HIA source differs')
RETAINED_SOURCE = RETAINED_BYTES.decode('utf-8', errors='strict')
# Preserve the old lock source except the private workspace extent in this
# separate extended component. The original R3 component remains unchanged.
_LOCK_EDITS = (
    ('length(w) != 73728', 'length(w) != 147456'),
    ('while index < 73728:', 'while index < 147456:'),
)
EXTENDED_LOCK_SOURCE = LOCK_SOURCE
for before, after in _LOCK_EDITS:
    if EXTENDED_LOCK_SOURCE.count(before) != 1 or after in EXTENDED_LOCK_SOURCE:
        raise ValueError('exact original lock extent admission')
    EXTENDED_LOCK_SOURCE = EXTENDED_LOCK_SOURCE.replace(before, after)
SOURCE = RETAINED_SOURCE + EXTENDED_LOCK_SOURCE + PAGE_SOURCE + COMMON_SOURCE
CONSTANTS = {
    'ABI': 4294967293,
    'RETAINED_MAGIC': int.from_bytes(b'HIARPGL1', 'little'),
    'EINTR': 18446744073709551612,
    'STATE_MAGIC': int.from_bytes(b'HIAPGST2', 'little'),
    'REQUEST_MAGIC': int.from_bytes(b'HIAPGOS2', 'little'),
    'EVENT_MAGIC': int.from_bytes(b'HIAPGEV2', 'little'),
    'OUTPUT_MAGIC': int.from_bytes(b'HIAPGOT2', 'little'),
    'DB_MAGIC0': int.from_bytes(b'SQLite f', 'big'),
    'DB_MAGIC1': int.from_bytes(b'ormat 3\0', 'big'),
}

def source_program():
    class Expand(ast.NodeTransformer):
        def visit_Name(self, node):
            if node.id in CONSTANTS:
                return ast.copy_location(ast.Constant(CONSTANTS[node.id]), node)
            return node
    return ast.unparse(ast.fix_missing_locations(Expand().visit(ast.parse(SOURCE)))) + '\n'

class PagerBuilder(Builder):
    """Select the existing checked copy opcode; no host file/lock computation."""
    def expr(self, expression):
        if (isinstance(expression, ast.Call) and isinstance(expression.func, ast.Name)
                and expression.func.id == 'copy_range'):
            if expression.keywords or len(expression.args) != 5:
                raise ValueError('copy_range requires five positional operands')
            values = [self.expr(value) for value in expression.args]
            if values[0][1] != 'mutbuf' or values[1][1] != 'readbuf':
                raise ValueError('copy_range requires distinct mutable/read owners')
            self.op('buffer.copy_range', values[:2] +
                    [self.cast(value, 'usize') for value in values[2:]])
            return self.c(0)
        return super().expr(expression)

def document():
    nodes = ast.parse(source_program()).body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    if len(names) != len(nodes):
        raise ValueError('duplicate Pager source function')
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args],
                             node.returns.id) for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = PagerBuilder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({
            'name': names[node.name],
            'params': [builder.param(value) for value in builder.params],
            'returns': [builder.returns],
            'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks,
        })
    return compact_authoring_cfg({
        'schema': 'hepta.hia.program.v8', 'module': 'sqlite_pager_retained_read_owner',
        'functions': functions,
    })

def main():
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    with args.output.open('x', encoding='utf-8', newline='\n') as stream:
        stream.write(render_assembly(document()))

if __name__ == '__main__':
    main()

"""Shared HIA helpers for the Pager owner. No host I/O or host state machine."""
SOURCE = r'''
def zero_event_tail(s:readbuf) -> u64:
    index = 96
    while index < 128:
        if byte(s, index) != 0:
            return 0
        index = index + 1
    return 1

def issue(o:mutbuf, w:mutbuf, phase:u64, operation:u64, handle:u64, a:u64, b:u64, c:u64) -> u32:
    if get(w, 24) == 18446744073709551615:
        put(w, 80, 7)
        put(w, 352, get(w, 8))
        put(w, 8, 203)
        return outcome(o, w, 132)
    put(w, 8, phase)
    put(w, 24, get(w, 24) + 1)
    put(w, 32, operation)
    put(w, 40, handle)
    put(w, 48, a)
    put(w, 56, b)
    put(w, 64, c)
    put(o, 0, REQUEST_MAGIC)
    put(o, 8, 2)
    put(o, 16, get(w, 16))
    put(o, 24, get(w, 24))
    put(o, 32, operation)
    put(o, 40, handle)
    put(o, 48, a)
    put(o, 56, b)
    put(o, 64, c)
    index = 72
    while index < 128:
        put(o, index, 0)
        index = index + 8
    return 1

def reissue(o:mutbuf, w:mutbuf) -> u32:
    # Only HIA decides EINTR retry, with a fresh sequence for each OS attempt.
    return issue(o, w, get(w, 8), get(w, 384), get(w, 40), get(w, 48), get(w, 56), get(w, 64))

def outcome(o:mutbuf, w:mutbuf, status:u64) -> u32:
    put(o, 0, OUTPUT_MAGIC)
    put(o, 8, 2)
    put(o, 16, get(w, 16))
    put(o, 24, status)
    put(o, 32, get(w, 80))
    put(o, 40, get(w, 88))
    put(o, 48, get(w, 352))
    put(o, 56, get(w, 96))
    put(o, 64, get(w, 104))
    put(o, 72, get(w, 128))
    put(o, 80, get(w, 136))
    put(o, 88, get(w, 144))
    put(o, 96, get(w, 152))
    put(o, 104, get(w, 224))
    put(o, 112, get(w, 232))
    put(o, 120, get(w, 280))
    return status

def fail(o:mutbuf, w:mutbuf, kind:u64, raw:u64) -> u32:
    if get(w, 80) == 0:
        put(w, 80, kind)
        put(w, 88, raw)
        put(w, 352, get(w, 8))
    return cleanup(o, w)

def cleanup(o:mutbuf, w:mutbuf) -> u32:
    if (get(w, 104) & 16) != 0:
        return issue(o, w, 100, 4, 2, 2, 123 + get(w, 160), 1)
    if (get(w, 104) & 32) != 0:
        return issue(o, w, 101, 4, 2, 2, 120, 1)
    if (get(w, 104) & 64) != 0:
        return issue(o, w, 102, 4, 2, 2, 122, 1)
    if (get(w, 104) & 8) != 0:
        return issue(o, w, 103, 4, 2, 2, 123 + get(w, 160), 1)
    if (get(w, 96) & 16) != 0:
        return issue(o, w, 104, 8, 2, 1, 0, 0)
    if (get(w, 96) & 8) != 0:
        return issue(o, w, 105, 8, 2, 0, 0, 0)
    if (get(w, 104) & 4) != 0:
        return issue(o, w, 106, 4, 2, 2, 128, 1)
    if (get(w, 96) & 4) != 0:
        return issue(o, w, 107, 9, 2, 0, 0, 0)
    if (get(w, 96) & 2) != 0:
        return issue(o, w, 108, 9, 1, 0, 0, 0)
    if (get(w, 104) & 2) != 0:
        return issue(o, w, 109, 4, 0, 2, 1073741826, 510)
    if (get(w, 104) & 1) != 0:
        return issue(o, w, 110, 4, 0, 2, 1073741824, 1)
    if (get(w, 96) & 1) != 0:
        return issue(o, w, 111, 9, 0, 0, 0, 0)
    put(w, 8, 202)
    return outcome(o, w, choose(get(w, 80) == 0, 130, 131))

def cleanup_return(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, 8)
    if phase == 107 or phase == 108 or phase == 111:
        # Linux close consumes the descriptor even when reporting EINTR.
        # It must never be retried: another allocation could reuse its number.
        if phase == 107:
            put(w, 96, get(w, 96) & 251)
        elif phase == 108:
            put(w, 96, get(w, 96) & 253)
        else:
            put(w, 96, get(w, 96) & 254)
        if word(s, 48) != 0 or word(s, 56) != 0:
            append_cleanup_error(w, phase, word(s, 48))
            if get(w, 80) == 0:
                put(w, 80, 1)
                put(w, 88, word(s, 48))
                put(w, 352, phase)
        return cleanup(o, w)
    if word(s, 48) != 0 or word(s, 56) != 0:
        # No guessed unlock/unmap success. This is an owned, failed terminal.
        # The process custodian must retain it or observe process termination.
        append_cleanup_error(w, phase, word(s, 48))
        if get(w, 80) == 0:
            put(w, 80, 1)
            put(w, 88, word(s, 48))
            put(w, 352, phase)
        put(w, 8, 203)
        return outcome(o, w, 132)
    if phase == 100:
        put(w, 104, get(w, 104) & 239)
    elif phase == 101:
        put(w, 104, get(w, 104) & 223)
    elif phase == 102:
        put(w, 104, get(w, 104) & 191)
    elif phase == 103:
        put(w, 104, get(w, 104) & 247)
    elif phase == 104:
        put(w, 96, get(w, 96) & 239)
    elif phase == 105:
        put(w, 96, get(w, 96) & 247)
    elif phase == 106:
        put(w, 104, get(w, 104) & 251)
    elif phase == 109:
        put(w, 104, get(w, 104) & 253)
    elif phase == 110:
        put(w, 104, get(w, 104) & 254)
    else:
        put(w, 8, 203)
        return outcome(o, w, 132)
    return cleanup(o, w)


def append_cleanup_error(w:mutbuf, phase:u64, raw:u64) -> u64:
    # First business/OS error stays unchanged. Keep the last cleanup error
    # plus the complete bounded cleanup error sequence, including close errors.
    put(w, 368, raw)
    put(w, 376, phase)
    count = get(w, 392)
    if count < 12:
        put(w, 768 + count * 16, phase)
        put(w, 776 + count * 16, raw)
        put(w, 392, count + 1)
    return 0

def regular_stat(s:readbuf) -> u64:
    if word(s, 48) != 0 or word(s, 56) != 144:
        return 0
    if (le(s, 152, 4) & 61440) != 32768:
        return 0
    if word(s, 144) == 0 or word(s, 176) > 9223372036854775807:
        return 0
    return 1

def is_busy(raw:u64) -> u64:
    return choose(raw == 18446744073709551605 or raw == 18446744073709551603, 1, 0)

def word(s:readbuf, at:u64) -> u64:
    return le(s, at, 8)

def le(s:readbuf, at:u64, count:u64) -> u64:
    value = 0
    index = 0
    while index < count:
        value = value | (byte(s, at + index) << (index * 8))
        index = index + 1
    return value

def get(w:mutbuf, at:u64) -> u64:
    value = 0
    index = 0
    while index < 8:
        value = value | (byte(w, at + index) << (index * 8))
        index = index + 1
    return value

def get32(w:mutbuf, at:u64) -> u64:
    return byte(w, at) | (byte(w, at + 1) << 8) | (byte(w, at + 2) << 16) | (byte(w, at + 3) << 24)

def get16(w:mutbuf, at:u64) -> u64:
    return byte(w, at) | (byte(w, at + 1) << 8)

def put(w:mutbuf, at:u64, value:u64) -> u64:
    index = 0
    while index < 8:
        store(w, at + index, (value >> (index * 8)) & 255)
        index = index + 1
    return 0

def be_mut(w:mutbuf, at:u64, count:u64) -> u64:
    value = 0
    index = 0
    while index < count:
        value = (value << 8) | byte(w, at + index)
        index = index + 1
    return value

def same(s:readbuf, a:u64, w:mutbuf, b:u64, count:u64) -> u64:
    index = 0
    while index < count:
        if byte(s, a + index) != byte(w, b + index):
            return 0
        index = index + 1
    return 1

def copy_mut(w:mutbuf, dst:u64, src:u64, count:u64) -> u64:
    index = 0
    while index < count:
        store(w, dst + index, byte(w, src + index))
        index = index + 1
    return 0
'''

"""Static HIA lock/endmark owner source. No Python runtime Pager policy.

This is one SOURCE fragment of the independent read-owner author. The companion
common/page fragments supply fixed HIA helpers. No function in SOURCE executes
as Python. Source creation is not generation or qualification.
"""
SOURCE = r'''
def sqlite_pager_read_owner(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) < 128 or length(o) != 128 or length(w) != 73728:
        return ABI
    if word(s, 0) != EVENT_MAGIC or word(s, 8) != 2:
        return ABI
    if word(s, 56) > 65536 or length(s) != 128 + word(s, 56):
        return ABI
    if zero_event_tail(s) == 0:
        return ABI
    event = word(s, 24)
    if event == 1:
        return owner_begin(s, o, w)
    if get(w, 0) != STATE_MAGIC or word(s, 16) != get(w, 16):
        return ABI
    if event == 2:
        if get(w, 32) == 0 or word(s, 32) != get(w, 24) or word(s, 40) != get(w, 32):
            return ABI
        if word(s, 64) != 0 or word(s, 72) != 0 or word(s, 80) != 0 or word(s, 88) != 0:
            return ABI
        # Preserve the consumed operation for an explicit fresh-sequence EINTR retry.
        put(w, 384, get(w, 32))
        # Receipt consumption precedes every further native effect.
        put(w, 32, 0)
        return owner_return(s, o, w)
    if get(w, 32) != 0 or word(s, 32) != 0 or word(s, 40) != 0 or word(s, 48) != 0 or word(s, 56) != 0:
        return ABI
    if word(s, 72) != 0 or word(s, 80) != 0 or word(s, 88) != 0:
        return ABI
    if event == 3 and get(w, 8) == 200:
        return page_begin(s, o, w)
    if event == 5 and get(w, 8) == 201:
        if word(s, 64) != get(w, 280):
            return ABI
        put(w, 8, 200)
        return outcome(o, w, 128)
    if event == 4 and get(w, 8) == 200 and word(s, 64) == 0:
        return cleanup(o, w)
    return ABI

def owner_begin(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if word(s, 16) == 0 or word(s, 32) != 0 or word(s, 40) != 0 or word(s, 48) != 0 or word(s, 56) != 0:
        return ABI
    if word(s, 64) != 34600 and word(s, 64) != 35302:
        return ABI
    if word(s, 72) != 0 or word(s, 80) != 0 or word(s, 88) != 0:
        return ABI
    index = 0
    while index < 73728:
        if byte(w, index) != 0:
            return ABI
        index = index + 1
    put(w, 0, STATE_MAGIC)
    put(w, 16, word(s, 16))
    put(w, 72, word(s, 64))
    # A state/context pair has exactly one BEGIN and no descriptor reopen.
    return issue(o, w, 1, 1, 0, 0, 0, 0)

def owner_return(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, 8)
    if phase >= 100 and phase < 120:
        if phase != 107 and phase != 108 and phase != 111 and word(s, 48) == EINTR:
            if word(s, 56) != 0:
                return cleanup_return(s, o, w)
            return reissue(o, w)
        return cleanup_return(s, o, w)
    # The leaf performs no hidden EINTR retry. CLOSE is handled above and
    # consumed once even on Linux EINTR. SLEEP exposes its remaining timespec.
    if word(s, 48) == EINTR:
        if phase == 38:
            return sleep_interrupted(s, o, w)
        if word(s, 56) != 0:
            return fail(o, w, 7, word(s, 48))
        return reissue(o, w)
    if phase == 60:
        return read_return(s, o, w)
    if phase >= 40 and phase <= 43:
        return index_return(s, o, w)
    if phase <= 13:
        return opening_return(s, o, w)
    if phase >= 20 and phase <= 25:
        return header_return(s, o, w)
    if phase >= 26 and phase <= 38:
        return reader_return(s, o, w)
    return fail(o, w, 7, 0)

def opening_return(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, 8)
    if phase == 1 or phase == 7 or phase == 9:
        if word(s, 48) > 2147483647 or word(s, 56) != 0:
            return fail(o, w, 1, word(s, 48))
        if phase == 1:
            put(w, 96, get(w, 96) | 1)
            return issue(o, w, 2, 2, 0, 0, 0, 0)
        if phase == 7:
            put(w, 96, get(w, 96) | 2)
            return issue(o, w, 8, 2, 1, 0, 0, 0)
        put(w, 96, get(w, 96) | 4)
        return issue(o, w, 10, 2, 2, 0, 0, 0)
    if phase == 2 or phase == 8 or phase == 10:
        if regular_stat(s) == 0:
            return fail(o, w, 1, word(s, 48))
        if phase == 2:
            put(w, 288, word(s, 176))
            put(w, 296, word(s, 128))
            put(w, 304, word(s, 136))
            return issue(o, w, 3, 4, 0, 0, 1073741824, 1)
        if phase == 8:
            if word(s, 128) == get(w, 296) and word(s, 136) == get(w, 304):
                return fail(o, w, 4, 0)
            put(w, 312, word(s, 128))
            put(w, 320, word(s, 136))
            return issue(o, w, 9, 1, 2, 0, 0, 0)
        if word(s, 176) < 32768:
            return fail(o, w, 4, 0)
        if word(s, 128) == get(w, 296) and word(s, 136) == get(w, 304):
            return fail(o, w, 4, 0)
        if word(s, 128) == get(w, 312) and word(s, 136) == get(w, 320):
            return fail(o, w, 4, 0)
        put(w, 328, word(s, 128))
        put(w, 336, word(s, 136))
        return dms_attempt(o, w)
    if phase == 11:
        if word(s, 48) != 0 or word(s, 56) != 32:
            return fail(o, w, 1, word(s, 48))
        # Linux LP64 struct flock: type:i16, whence:i16, pad4,
        # start:i64, len:i64, pid:i32, pad4. Keep all 32 raw bytes.
        copy_range(w, s, 704, 128, 32)
        if le(s, 128, 2) == 2:
            return fail(o, w, 4, 0)
        if le(s, 128, 2) == 1:
            return dms_attempt(o, w)
        if le(s, 128, 2) != 0:
            return fail(o, w, 7, 0)
        return issue(o, w, 12, 4, 2, 0, 128, 1)
    if phase == 13:
        # mmap returns its real address, not a normalized zero result.
        if word(s, 48) > 9223372036854775807 or word(s, 56) != 0:
            return fail(o, w, 1, word(s, 48))
        put(w, 96, get(w, 96) | 8)
        return issue(o, w, 20, 6, 2, 0, 48, 0)
    if phase == 12 and is_busy(word(s, 48)) == 1 and word(s, 56) == 0:
        return dms_attempt(o, w)
    if word(s, 56) != 0:
        return fail(o, w, 7, word(s, 48))
    if word(s, 48) != 0:
        return fail(o, w, choose(is_busy(word(s, 48)) == 1, 2, 1), word(s, 48))
    if phase == 3:
        put(w, 104, get(w, 104) | 1)
        return issue(o, w, 4, 4, 0, 0, 1073741826, 510)
    if phase == 4:
        put(w, 104, get(w, 104) | 2)
        return issue(o, w, 5, 4, 0, 2, 1073741824, 1)
    if phase == 5:
        put(w, 104, get(w, 104) & 254)
        return start_read(o, w, 0, 0, 100, 1)
    if phase == 12:
        put(w, 104, get(w, 104) | 4)
        return issue(o, w, 13, 5, 2, 0, 0, 0)
    return fail(o, w, 7, 0)

def after_db_header(o:mutbuf, w:mutbuf) -> u32:
    if be_mut(w, 4096, 8) != DB_MAGIC0 or be_mut(w, 4104, 8) != DB_MAGIC1:
        return fail(o, w, 5, 0)
    size = be_mut(w, 4112, 2)
    if size == 1:
        size = 65536
    if size < 512 or size > 65536 or (size & (size - 1)) != 0:
        return fail(o, w, 5, 0)
    # This first owner supports existing WAL databases only. A rollback or
    # write-version transition is explicit UNSUPPORTED, not SQLITE_BUSY.
    if byte(w, 4114) != 2 or byte(w, 4115) != 2:
        return fail(o, w, 4, 0)
    if byte(w, 4116) > 255 or size - byte(w, 4116) < 480:
        return fail(o, w, 5, 0)
    if byte(w, 4117) != 64 or byte(w, 4118) != 32 or byte(w, 4119) != 32:
        return fail(o, w, 5, 0)
    put(w, 128, size)
    # Raw DB page 1 is a preliminary WAL-mode/geometry observation only.
    # Snapshot nPage comes from the admitted published wal-index header.
    return issue(o, w, 7, 1, 1, 0, 0, 0)

def dms_attempt(o:mutbuf, w:mutbuf) -> u32:
    put(w, 120, 11)
    return retry_schedule(o, w)

def wal_attempt(o:mutbuf, w:mutbuf) -> u32:
    put(w, 120, 20)
    return retry_schedule(o, w)

def retry_schedule(o:mutbuf, w:mutbuf) -> u32:
    put(w, 112, get(w, 112) + 1)
    if get(w, 112) > 100:
        return fail(o, w, 3, 0)
    if get(w, 112) > 5:
        delay = 1000
        if get(w, 112) >= 10:
            delay = (get(w, 112) - 9) * (get(w, 112) - 9) * 39000
        return issue(o, w, 38, 10, 0, delay, 0, 0)
    return retry_resume(o, w)

def retry_resume(o:mutbuf, w:mutbuf) -> u32:
    if get(w, 120) == 11:
        return issue(o, w, 11, 11, 2, 0, 0, 0)
    return issue(o, w, 20, 6, 2, 0, 48, 0)

def header_return(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, 8)
    if phase == 22:
        if word(s, 56) != 0:
            return fail(o, w, 7, word(s, 48))
        if is_busy(word(s, 48)) == 1:
            return issue(o, w, 24, 4, 2, 0, 122, 1)
        if word(s, 48) != 0:
            return fail(o, w, 1, word(s, 48))
        put(w, 104, get(w, 104) | 32)
        return issue(o, w, 20, 6, 2, 0, 48, 0)
    if phase == 24:
        if word(s, 56) != 0:
            return fail(o, w, 7, word(s, 48))
        if word(s, 48) != 0:
